head.script:
scwin.onpageload = function () {
	// 이 화면이 widget 으로 쓰일 때만 $p.widget 객체가 있음
	if ($p.widget) {
		tbx_wid.setValue($p.widget.getWidgetId());
		tbx_cid.setValue($p.widget.getWidgetContainerId());
		tbx_cobj.setValue($p.widget.getWidgetContainer().getID());
	} else {
		tbx_wid.setValue("widget아님");
	}
};
